def diffWaysToCompute(expression: str) -> list[int]:
    # Helper function with memoization
    memo = {}

    def dfs(expr):
        if expr in memo:
            return memo[expr]
        res = []
        for i in range(len(expr)):
            if expr[i] in "+-*":
                # Split expression into left and right at operator
                left = dfs(expr[:i])
                right = dfs(expr[i+1:])
                # Compute all combinations
                for l in left:
                    for r in right:
                        if expr[i] == '+':
                            res.append(l + r)
                        elif expr[i] == '-':
                            res.append(l - r)
                        else:  # '*'
                            res.append(l * r)
        # Base case: entire substring is a number
        if not res:
            res.append(int(expr))
        memo[expr] = res
        return res

    return dfs(expression)
